"""Real JEE Main questions — Chemistry Unit 12: Coordination Compounds. Our own solutions; chk recomputes every
answer — oxidation state and d count from the formula, spin state from the ligand's field strength (cfield.py),
unpaired electrons, spin-only moments, CFSE, colour/wavelength orders from the spectrochemical series, and isomer
counts by brute-force enumeration over the octahedron's symmetry. Statement items are checked against a fact table."""
import math
from common import new_registry, pick, verify
from chemkit import stmt, ar, pickset, letters
from dblock import ATOM, E32, IE3, d_count
from cfield import LIG, ox_state, low_spin, unp_oct, unp_tet, unp_sq, cfse_oct, cfse_tet, mu, stereo, stereo_sq
P, add = new_registry()
RANK = {'I': 0, 'Br': 1, 'SCN': 2, 'S': 2, 'Cl': 3, 'F': 4, 'OH': 5, 'ox': 6, 'C2O4': 6, 'H2O': 7, 'NCS': 8, 'EDTA': 9, 'py': 10, 'NH3': 10,
        'en': 11, 'NO2': 12, 'CN': 13, 'CO': 14, 'PPh3': 13}
def fr(ligs): return sum(RANK[l] * k for l, k in ligs.items()) / sum(ligs.values())   # mean field rank
def C(m, charge, ligs, geom='oct', ls=None):
    """complex [M(ligs)]^charge → dict(ox, d, ls, n, t, e) (t/e: t2g/eg electrons for octahedral)"""
    ox = ox_state(charge, ligs); d = d_count(m, ox)
    if 'CO' in ligs and ox == 0: return dict(ox=0, d=10 if m == 'Ni' else d, ls=True, n=0, t=None, e=None)   # carbonyls pair up
    if geom == 'tet': return dict(ox=ox, d=d, ls=False, n=unp_tet(d), t=None, e=None)
    if geom == 'sq': return dict(ox=ox, d=d, ls=True, n=unp_sq(d), t=None, e=None)
    ls = low_spin(m, ox, ligs) if ls is None else ls; t, e = conf(d, ls)
    return dict(ox=ox, d=d, ls=ls, n=unp_oct(d, ls), t=t, e=e)
def conf(d, ls):
    if ls: t = min(d, 6); return t, d - t
    occ = [0] * 5
    for k in range(d): occ[k % 5] += 1
    return sum(occ[:3]), sum(occ[3:])
def optical(mono, bi=()):
    t, g = stereo(mono, bi); return 2 * (t - g)   # each chiral geometrical isomer is a pair of enantiomers

