def delta(m, charge, ligs): return fr(ligs) + 5 * (ox_state(charge, ligs) - 2)   # Δo rank: ligand field, then higher metal charge
def order_ok(seq, key, rising=True):
    v = [key(x) for x in seq]; return all((a < b) if rising else (a > b) for a, b in zip(v, v[1:]))
